 async function submitReview(){if(reviewBusy)return;const cleanName=reviewName.trim(),cleanComment=reviewText.trim();if(!cleanName||cleanName.length>60||cleanComment.length<5||cleanComment.length>800){setReviewNotice(lang==='sq'?'Vendos emrin dhe një koment prej 5 deri në 800 karaktere.':lang==='en'?'Enter your name and a comment between 5 and 800 characters.':'Gib deinen Namen und einen Kommentar mit 5 bis 800 Zeichen ein.');return}setReviewBusy(true);setReviewNotice('');try{const {data,error}=await supabase.from('customer_reviews').insert({user_id:userId,display_name:cleanName,rating:reviewRating,comment:cleanComment}).select('id,display_name,rating,comment,created_at').single();if(error)throw error;setReviews(old=>[data,...old]);setHasReviewed(true);setReviewText('');setReviewNotice(lang==='sq'?'Faleminderit! Vlerësimi yt u publikua.':lang==='en'?'Thank you! Your review has been published.':'Danke! Deine Bewertung wurde veröffentlicht.')}catch(e){setReviewNotice(e.code==='23505'?(lang==='sq'?'Kjo llogari ka dërguar tashmë një vlerësim.':lang==='en'?'This account has already submitted a review.':'Dieses Konto hat bereits eine Bewertung abgegeben.'):(e.message||'Nuk u dërgua vlerësimi.'))}finally{setReviewBusy(false)}}
