 useEffect(()=>{let alive=true;(async()=>{if(!userId||!supabase){setCloudLoaded(true);return}const {data,error}=await supabase.from('projects').select('*').order('updated_at',{ascending:false});if(!alive)return;if(error){console.error('Cloud project load failed',error);setNotice(lang==='sq'?'Projektet nuk u ngarkuan nga cloud. Kontrollo lidhjen dhe provo përsëri.':'Projekte konnten nicht aus der Cloud geladen werden. Bitte Verbindung prüfen.');setCloudLoaded(true);return}const cloud=await Promise.all((data||[]).map(async p=>{let imageData='';if(p.image_url){const {data:signed}=await supabase.storage.from('aais-assets').createSignedUrl(p.image_url,3600);imageData=signed?.signedUrl||''}return {id:/^\\d+$/.test(p.client_ref)?Number(p.client_ref):p.client_ref,title:p.title,prompt:p.prompt,mode:p.mode,ratio:p.aspect_ratio,duration:String(p.duration_seconds),style:p.visual_style,imageName:p.image_name||'',imageData,created:new Date(p.created_at).toLocaleDateString(),status:p.status}}));if(alive){setProjects(local=>{const byId=new Map(cloud.map(p=>[String(p.id),p]));for(const p of local){if(!byId.has(String(p.id)))byId.set(String(p.id),p)}return [...byId.values()]});setCloudLoaded(true)}})();return()=>{alive=false}},[userId]);
